const api=async(path,opts={})=>{if(offlineMode)return localApi(path,opts);const r=await fetch('/api'+path,{headers:{'Content-Type':'application/json'},...opts});if(r.status===401){location.href='/login.html';throw Error('Sign in required')}const d=await r.json();if(!r.ok)throw Error(d.error||'Something went wrong');return d};
const fmtMoney=n=>Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
const fmtDate=d=>d?new Date(d+(String(d).length===10?'T12:00:00':'')).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const fmtDateTime=d=>{if(!d)return '—';const text=String(d),date=new Date(text+(text.length===10?'T12:00:00':''));return text.length===10?fmtDate(text):date.toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'})};
const reminderLabel=n=>Number(n)===0?'No reminder':Number(n)>=1440?`${Number(n)/1440} day${Number(n)===1440?'':'s'} before`:`${Number(n)/60} hour${Number(n)===60?'':'s'} before`;
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const initials=c=>((c.first_name?.[0]||'')+(c.last_name?.[0]||'')).toUpperCase();
const phoneHref=phone=>String(phone||'').replace(/[^\d+]/g,'');
function contactActions(c,compact=false){const phone=phoneHref(c.phone),email=String(c.email||'').trim();if(!phone&&!email)return '<span class="contact-actions-empty">—</span>';return `<span class="contact-actions ${compact?'compact':''}">${phone?`<a class="contact-action" data-comm-kind="Call" data-contact-id="${c.id}" href="tel:${esc(phone)}" aria-label="Call ${esc(c.first_name)}" title="Call ${esc(c.phone)}">☎<span>Call</span></a><a class="contact-action" data-comm-kind="Text" data-contact-id="${c.id}" href="sms:${esc(phone)}" aria-label="Text ${esc(c.first_name)}" title="Text ${esc(c.phone)}">💬<span>Text</span></a>`:''}${email?`<a class="contact-action" data-comm-kind="Email" data-contact-id="${c.id}" href="mailto:${esc(email)}" aria-label="Email ${esc(c.first_name)}" title="Email ${esc(c.email)}">✉<span>Email</span></a>`:''}</span>`}
const numericValue=value=>{const values=String(value||'').replace(/,/g,'').match(/\d+(?:\.\d+)?/g)||[];return values.length?Number(values.at(-1)):0};
function propertyMatch(contact,listing){const desiredBeds=Number(contact.bedrooms||0),listingBeds=Number(listing.bedrooms||0),budgetMax=Number(contact.budget_max||numericValue(contact.budget)),price=Number(listing.current_price||0),wantedArea=String(contact.area||'').trim().toLowerCase(),listingArea=String(listing.area||listing.address||'').toLowerCase(),wantedPool=String(contact.pool||''),listingPool=String(listing.pool||''),feature=String(contact.important_feature||'').trim().toLowerCase(),features=String(listing.important_features||listing.marketing_notes||'').toLowerCase();const checks=[];if(desiredBeds)checks.push([listingBeds>=desiredBeds,35,`${listingBeds||'—'} bedrooms vs ${desiredBeds}+ wanted`]);if(budgetMax)checks.push([price<=budgetMax,30,`${fmtMoney(price)} vs ${fmtMoney(budgetMax)} maximum`]);if(wantedArea)checks.push([listingArea.includes(wantedArea)||wantedArea.split(/[,/]/).some(x=>x.trim()&&listingArea.includes(x.trim())),20,`Area: ${contact.area}`]);if(wantedPool==='Yes')checks.push([listingPool==='Yes',10,'Pool required']);if(feature)checks.push([features.includes(feature)||feature.split(/[,/]/).some(x=>x.trim().length>2&&features.includes(x.trim())),5,`Feature: ${contact.important_feature}`]);const possible=checks.reduce((n,x)=>n+x[1],0),earned=checks.reduce((n,x)=>n+(x[0]?x[1]:0),0),score=possible?Math.round(earned/possible*100):0;return {score,reasons:checks.filter(x=>x[0]).map(x=>x[2]),misses:checks.filter(x=>!x[0]).map(x=>x[2]),eligible:possible>0&&score>=60&&(!desiredBeds||listingBeds>=desiredBeds)}}
function matchingBuyers(listing){const active=new Set((state.data.opportunities||[]).filter(x=>x.type==='buyer'&&x.status!=='closed'&&!['Closed','Nurture/Lost'].includes(x.stage)).map(x=>x.contact_id));return (state.data.contacts||[]).filter(c=>(c.roles||[]).includes('Buyer')&&(!active.size||active.has(c.id))).map(contact=>({contact,...propertyMatch(contact,listing)})).filter(x=>x.eligible).sort((a,b)=>b.score-a.score)}
function matchingListings(contact){return (state.data.listings||[]).filter(x=>['Active','Coming Soon'].includes(x.status)).map(listing=>({listing,...propertyMatch(contact,listing)})).filter(x=>x.eligible).sort((a,b)=>b.score-a.score)}
const googleDate=value=>new Date(value).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
function googleCalendarUrl(title,start,details=''){if(!start)return '#';const begins=new Date(start),ends=new Date(begins.getTime()+60*60*1000),params=new URLSearchParams({action:'TEMPLATE',text:title,dates:`${googleDate(begins)}/${googleDate(ends)}`,details});return `https://calendar.google.com/calendar/render?${params}`}
function calendarAction(title,start,details='',label='Calendar'){return start?`<a class="btn calendar-action" href="${esc(googleCalendarUrl(title,start,details))}" target="_blank" rel="noopener" title="Add to Google Calendar">📅 ${label}</a>`:''}
function toast(msg,bad=false){const t=$('#toast');t.textContent=msg;t.style.background=bad?'#9f4339':'';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function header(kicker,title,sub,button=''){return `<div class="pagehead"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${button}</div></div>`}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`}
function empty(title,text){return `<div class="empty"><strong>${title}</strong>${text}</div>`}
function transactionMilestones(rows=[]){const fields=[['inspection_date','Inspection'],['appraisal_date','Appraisal'],['financing_deadline','Financing deadline'],['final_walkthrough_date','Final Walk Through'],['closing_date','Closing']];return rows.filter(t=>t.status!=='Cancelled').flatMap(t=>{const done=t.completed_milestones||[];return fields.filter(([key])=>t[key]).map(([key,label])=>({_calendar:true,id:`tx-${t.id}-${key}`,milestone_key:key,title:`${label} — ${t.property}`,contact_name:t.buyer_name||t.seller_name||'Transaction milestone',due_at:t[key],priority:'Calendar',status:done.includes(key)||t.status==='Closed'?'completed':'open',transaction_id:t.id}));});}
