const calendarKey=value=>String(value||'').slice(0,10);
function calendarItems(){const items=[];for(const task of state.data.tasks||[])if(!task._calendar&&task.status!=='completed'&&task.due_at)items.push({date:calendarKey(task.due_at),time:String(task.due_at).slice(11,16),title:task.title,detail:task.contact_name||'Task',kind:'task',id:task.id,status:task.status});for(const contact of state.data.contacts||[]){const name=`${contact.first_name} ${contact.last_name}`.trim();if(contact.next_follow_up)items.push({date:calendarKey(contact.next_follow_up),title:`Follow-up — ${name}`,detail:'Contact follow-up',kind:'followup',id:contact.id});if(contact.last_contact)items.push({date:calendarKey(contact.last_contact),title:`Last contact — ${name}`,detail:'Contact history',kind:'contact',id:contact.id})}const fields=[['contract_date','Contract date'],['inspection_date','Inspection'],['appraisal_date','Appraisal'],['financing_deadline','Financing deadline'],['final_walkthrough_date','Final Walk Through'],['closing_date','Closing']];for(const transaction of state.data.transactions||[])if(transaction.status!=='Cancelled')for(const [field,label] of fields)if(transaction[field])items.push({date:calendarKey(transaction[field]),time:String(transaction[field]).slice(11,16),title:`${label} — ${transaction.property}`,detail:transaction.buyer_name||transaction.seller_name||'Transaction',kind:'transaction',id:transaction.id});return items.filter(x=>x.date).sort((a,b)=>`${a.date}${a.time||''}`.localeCompare(`${b.date}${b.time||''}`))}
function calendarEntry(item){return `<button class="calendar-event ${item.kind}" data-calendar-kind="${item.kind}" data-calendar-id="${item.id}" title="${esc(item.title)}">${item.time?`<span>${esc(item.time)}</span>`:''}${esc(item.title)}</button>`}
function bindCalendarActions(){$$('[data-calendar-kind]').forEach(button=>button.onclick=()=>{const id=Number(button.dataset.calendarId),kind=button.dataset.calendarKind;if(kind==='task'){const task=(state.data.tasks||[]).find(x=>!x._calendar&&x.id===id);if(task)openForm('tasks',task,task.id)}else if(kind==='transaction'){const transaction=(state.data.transactions||[]).find(x=>x.id===id);if(transaction)openTransaction(transaction)}else showContact(id)})}
function drawCalendar(){const today=new Date(),base=state.calendarMonth?new Date(`${state.calendarMonth}T12:00:00`):new Date(today.getFullYear(),today.getMonth(),1,12),year=base.getFullYear(),month=base.getMonth(),first=new Date(year,month,1,12),start=new Date(year,month,1-first.getDay(),12),items=calendarItems(),todayKey=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`,cells=[];state.calendarMonth=`${year}-${String(month+1).padStart(2,'0')}-01`;for(let index=0;index<42;index++){const day=new Date(start);day.setDate(start.getDate()+index);const key=`${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`,dayItems=items.filter(x=>x.date===key);cells.push(`<div class="calendar-day ${day.getMonth()!==month?'outside':''} ${key===todayKey?'today':''}"><div class="calendar-date">${day.getDate()}</div>${dayItems.slice(0,4).map(calendarEntry).join('')}${dayItems.length>4?`<small class="calendar-more">+${dayItems.length-4} more</small>`:''}</div>`)}const upcoming=items.filter(x=>x.date>=todayKey).slice(0,12);$('#app').innerHTML=header('SCHEDULE','Calendar','Tasks, follow-ups, contact history, and transaction dates together.',`<button class="btn primary" data-add="tasks">＋ Add task</button>`)+`<section class="card calendar-card"><div class="calendar-toolbar"><button class="btn" id="calendarPrev" aria-label="Previous month">←</button><button class="btn" id="calendarToday">Today</button><h2>${first.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><button class="btn" id="calendarNext" aria-label="Next month">→</button></div><div class="calendar-legend"><span class="task">Task</span><span class="followup">Next follow-up</span><span class="contact">Last contact</span><span class="transaction">Transaction</span></div><div class="calendar-scroll"><div class="calendar-grid"><div class="calendar-weekday">Sun</div><div class="calendar-weekday">Mon</div><div class="calendar-weekday">Tue</div><div class="calendar-weekday">Wed</div><div class="calendar-weekday">Thu</div><div class="calendar-weekday">Fri</div><div class="calendar-weekday">Sat</div>${cells.join('')}</div></div></section><section class="card calendar-upcoming"><div class="card-head"><h2>Upcoming dates</h2></div><div class="list">${upcoming.length?upcoming.map(item=>`<div class="list-item"><div class="datebox"><b>${Number(item.date.slice(8))}</b>${new Date(`${item.date}T12:00:00`).toLocaleString('en-US',{month:'short'}).toUpperCase()}</div><div class="grow"><p>${esc(item.title)}</p><small>${item.time?`${esc(item.time)} · `:''}${esc(item.detail)}</small></div><button class="btn" data-calendar-kind="${item.kind}" data-calendar-id="${item.id}">Open</button></div>`).join(''):empty('No upcoming dates','Add a task, follow-up, or transaction milestone.')}</div></section>`;bind();bindCalendarActions();$('#calendarPrev').onclick=()=>{base.setMonth(base.getMonth()-1);state.calendarMonth=`${base.getFullYear()}-${String(base.getMonth()+1).padStart(2,'0')}-01`;drawCalendar()};$('#calendarNext').onclick=()=>{base.setMonth(base.getMonth()+1);state.calendarMonth=`${base.getFullYear()}-${String(base.getMonth()+1).padStart(2,'0')}-01`;drawCalendar()};$('#calendarToday').onclick=()=>{state.calendarMonth=null;drawCalendar()}}
function smartContactCard(c){return `<article class="smart-contact" data-id="${c.id}"><div class="person"><span class="initials">${initials(c)}</span><div class="grow"><b>${esc(c.first_name)} ${esc(c.last_name)}</b><small>${esc(c.source||'Contact')} · Last contact ${fmtDate(c.last_contact)}</small></div></div>${contactActions(c,true)}</article>`}
function draftRow(d){return `<div class="list-item draft-item"><div class="grow"><p>${esc(d.subject||`${d.channel} draft`)}</p><small>${esc(d.contact_name||'Unassigned')} · ${esc(d.channel)}${d.due_at?` · Recommended ${fmtDateTime(d.due_at)}`:''}</small><small class="draft-source">${esc(d.source||'Manual recommendation')}</small></div><button class="btn draft-open" data-id="${d.id}">Review</button></div>`}
function draftSuggestion(contact,channel='Email'){const first=contact?.first_name||'there',subject='Checking in',body=`Hi ${first},\n\nI wanted to check in and see how I can help with your real-estate plans. When you have a moment, let me know what questions you have or what your next step looks like.\n\nEric Hepple\nParadise Property Brokers, Inc.`;return {channel,subject,body}}
function propertyDraft(contact,listing){return {channel:'Email',subject:`A property that may fit: ${listing.address}`,body:`Hi ${contact.first_name||'there'},\n\nI have a property at ${listing.address} that may fit what you are looking for. It is listed at ${fmtMoney(listing.current_price)}${listing.bedrooms?` with ${listing.bedrooms} bedrooms`:''}.\n\nWould you like more information or to schedule a showing?\n\nEric Hepple\nParadise Property Brokers, Inc.`}}
async function savePropertyDraft(contact,listing){const message=propertyDraft(contact,listing);await api('/communication_drafts',{method:'POST',body:JSON.stringify({contact_id:contact.id,...message,status:'draft',source:`Property match: ${listing.address}`})});toast(`Draft created for ${contact.first_name}`)}
async function openListingMatches(listing){await load('contacts','opportunities','listings');const matches=matchingBuyers(listing);$('#modalKicker').textContent='BUYER PROPERTY MATCHING';$('#modalTitle').textContent=listing.address;$('#modalForm').innerHTML=`<div class="match-panel"><div class="match-summary"><strong>${matches.length}</strong><span>active buyer${matches.length===1?'':'s'} match this property</span></div>${matches.length?matches.map(({contact,score,reasons,misses})=>`<article class="match-card"><div><h3>${esc(contact.first_name)} ${esc(contact.last_name)}</h3><p>${reasons.map(esc).join(' · ')}</p>${misses.length?`<small>Review: ${misses.map(esc).join(' · ')}</small>`:''}</div><div class="match-actions">${badge(`${score}%`,'gold')}<button type="button" class="btn open-match-contact" data-id="${contact.id}">Profile</button><button type="button" class="btn primary draft-property-match" data-id="${contact.id}">Create draft</button></div></article>`).join(''):empty('No matching buyers yet','Add buyer budget, minimum bedrooms, area, pool, or important features to improve matching.')}<div class="form-actions"><button type="button" class="btn" id="closeMatches">Close</button><button type="button" class="btn primary" id="matchesQr">Open-house QR</button></div></div>`;$('#modal').classList.remove('hidden');$('#closeMatches').onclick=closeModal;$('#matchesQr').onclick=()=>openOpenHouseQr(listing);$$('.open-match-contact').forEach(b=>b.onclick=()=>{closeModal();showContact(Number(b.dataset.id))});$$('.draft-property-match').forEach(b=>b.onclick=()=>savePropertyDraft(state.data.contacts.find(c=>c.id===Number(b.dataset.id)),listing))}
function openOpenHouseQr(listing){const url=new URL('./open-house.html',location.href);url.searchParams.set('listing',String(listing.id));url.searchParams.set('address',listing.address);const preview=new URL(url);preview.searchParams.set('preview','1');const qr=`https://quickchart.io/qr?size=340&margin=2&text=${encodeURIComponent(url.href)}`;$('#modalKicker').textContent='OPEN-HOUSE SIGN-IN';$('#modalTitle').textContent=listing.address;$('#modalForm').innerHTML=`<div class="qr-panel"><img src="${esc(qr)}" alt="Open-house sign-in QR code"><h3>Scan to sign in</h3><p>Visitors can enter their contact information, timeframe, and property preferences. After signing in, they will see the public marketing page for this listing.</p><input id="openHouseLink" value="${esc(url.href)}" readonly><div class="form-actions"><button type="button" class="btn" id="closeQr">Close</button><a class="btn" href="${esc(preview.href)}" target="_blank" rel="noopener">Preview visitor page</a><button type="button" class="btn" id="copyQrLink">Copy link</button><button type="button" class="btn primary" id="shareQrLink">Share</button></div></div>`;$('#modal').classList.remove('hidden');$('#closeQr').onclick=closeModal;$('#copyQrLink').onclick=async()=>{await navigator.clipboard.writeText(url.href);toast('Open-house link copied')};$('#shareQrLink').onclick=async()=>{if(navigator.share)await navigator.share({title:`Open house — ${listing.address}`,text:'Please sign in for the open house.',url:url.href});else{await navigator.clipboard.writeText(url.href);toast('Link copied')}}}
async function drawContactMatches(){if(!state.contact)return;await load('listings');const matches=matchingListings(state.contact);$('#contactPanel').innerHTML=`<div class="card-head"><div><h2>Matching listings</h2><small>${matches.length} current match${matches.length===1?'':'es'}</small></div></div><div class="match-panel embedded">${matches.length?matches.map(({listing,score,reasons})=>`<article class="match-card"><div><h3>${esc(listing.address)}</h3><p>${fmtMoney(listing.current_price)} · ${reasons.map(esc).join(' · ')}</p></div><div class="match-actions">${badge(`${score}%`,'gold')}<button class="btn create-contact-property-draft" data-id="${listing.id}">Create draft</button></div></article>`).join(''):empty('No matching listings','Add buyer criteria or listing details to generate matches.')}</div>`;$$('.create-contact-property-draft').forEach(b=>b.onclick=()=>savePropertyDraft(state.contact,state.data.listings.find(x=>x.id===Number(b.dataset.id))))}
async function openSuggestedDraftForm(contact=state.contact){await load('contacts');const selected=contact||state.data.contacts[0];if(!selected)return toast('Add a contact before creating a draft',true);const suggestion=draftSuggestion(selected);$('#modalKicker').textContent='MESSAGE RECOMMENDATION';$('#modalTitle').textContent='Create draft';$('#modalForm').innerHTML=`<div class="form-grid"><label class="field"><span>Contact</span><select id="draftContact">${state.data.contacts.map(c=>`<option value="${c.id}" ${c.id===selected.id?'selected':''}>${esc(c.first_name)} ${esc(c.last_name)}</option>`).join('')}</select></label><label class="field"><span>Type</span><select id="draftChannel"><option>Email</option><option>Text</option></select></label><label class="field full"><span>Subject</span><input id="draftSubject" value="${esc(suggestion.subject)}"></label><label class="field full"><span>Message</span><textarea id="draftBody">${esc(suggestion.body)}</textarea></label><div class="field full"><small>Nothing is sent automatically. The draft stays here until you review it.</small></div><div class="form-actions"><button type="button" class="btn" id="cancelDraft">Cancel</button><button type="button" class="btn primary" id="saveSuggestedDraft">Save draft</button></div></div>`;$('#modal').classList.remove('hidden');$('#cancelDraft').onclick=closeModal;$('#draftContact').onchange=()=>{const c=state.data.contacts.find(x=>x.id===Number($('#draftContact').value)),s=draftSuggestion(c,$('#draftChannel').value);$('#draftSubject').value=s.subject;$('#draftBody').value=s.body};$('#saveSuggestedDraft').onclick=async()=>{await api('/communication_drafts',{method:'POST',body:JSON.stringify({contact_id:Number($('#draftContact').value),channel:$('#draftChannel').value,subject:$('#draftSubject').value,body:$('#draftBody').value,status:'draft',source:'Manual recommendation'})});closeModal();toast('Draft saved for review');go('inbox')}}
async function openDraft(id){await load('communication_drafts','contacts');const draft=state.data.communication_drafts.find(x=>x.id===id),contact=state.data.contacts.find(x=>x.id===draft?.contact_id);if(!draft)return;$('#modalKicker').textContent='REVIEW BEFORE SENDING';$('#modalTitle').textContent=`${draft.channel} draft`;$('#modalForm').innerHTML=`<div class="form-grid"><div class="field full"><span>Contact</span><b>${esc(contact?`${contact.first_name} ${contact.last_name}`:'Unassigned')}</b></div><label class="field"><span>Type</span><select id="reviewChannel"><option ${draft.channel==='Email'?'selected':''}>Email</option><option ${draft.channel==='Text'?'selected':''}>Text</option></select></label><label class="field full"><span>Subject</span><input id="reviewSubject" value="${esc(draft.subject||'')}"></label><label class="field full"><span>Message</span><textarea id="reviewBody">${esc(draft.body||'')}</textarea></label><div class="field full"><small>This opens your Mail or Messages app. You remain in control of the final Send button.</small></div><div class="form-actions draft-actions"><button type="button" class="btn" id="saveDraft">Save draft</button><a class="btn primary" id="openDraftApp" target="_blank" rel="noopener">Open in app</a><button type="button" class="btn" id="markDraftSent">Mark sent</button></div></div>`;$('#modal').classList.remove('hidden');const values=()=>({channel:$('#reviewChannel').value,subject:$('#reviewSubject').value,body:$('#reviewBody').value}),updateLink=()=>{const v=values(),email=contact?.email||'',phone=phoneHref(contact?.phone),href=v.channel==='Email'?`mailto:${email}?subject=${encodeURIComponent(v.subject)}&body=${encodeURIComponent(v.body)}`:`sms:${phone}?&body=${encodeURIComponent(v.body)}`;$('#openDraftApp').href=href;$('#openDraftApp').textContent=v.channel==='Email'?'Open in Mail':'Open in Messages'};['reviewChannel','reviewSubject','reviewBody'].forEach(key=>$(`#${key}`).oninput=updateLink);updateLink();$('#saveDraft').onclick=async()=>{await api('/communication_drafts/'+id,{method:'PUT',body:JSON.stringify(values())});toast('Draft saved')};$('#openDraftApp').onclick=()=>{api('/communication_drafts/'+id,{method:'PUT',body:JSON.stringify(values())});toast('Draft opened — mark it sent afterward')};$('#markDraftSent').onclick=async()=>{const v=values();await api('/communication_drafts/'+id,{method:'PUT',body:JSON.stringify({...v,status:'sent',sent_at:new Date().toISOString()})});await api('/activities',{method:'POST',body:JSON.stringify({contact_id:draft.contact_id,type:v.channel,direction:'Outgoing',subject:v.subject,body:v.body,occurred_at:new Date().toISOString()})});closeModal();toast('Communication marked sent');go('inbox')}}
function contactsRows(cs){return cs.map(c=>`<tr class="clickable contact-row" data-id="${c.id}"><td><div class="person"><span class="initials">${initials(c)}</span><div><b>${esc(c.first_name)} ${esc(c.last_name)}</b><small>${esc(c.email||c.phone||'No contact details')}</small></div></div></td><td>${(c.roles||[]).map(x=>badge(x)).join(' ')||badge('Contact','gray')}</td><td>${esc(c.source)}</td><td>${fmtDate(c.last_contact)}</td><td>${fmtDate(c.next_follow_up)}</td><td>${contactActions(c,true)}</td></tr>`).join('')||`<tr><td colspan="6">${empty('No contacts yet','Add the first person to your CRM.')}</td></tr>`}
function filterContacts(){const q=$('#localFilter').value.toLowerCase(),r=$('#roleFilter').value,s=$('#sourceFilter').value;const a=state.data.contacts.filter(c=>JSON.stringify(c).toLowerCase().includes(q)&&(!r||(c.roles||[]).includes(r))&&(!s||c.source===s));$('#contactRows').innerHTML=contactsRows(a);bindContactRows();}
async function pipeline(type,stages){await load('opportunities');const a=state.data.opportunities.filter(x=>x.type===type);$('#app').innerHTML=header('OPPORTUNITIES',`${type==='buyer'?'Buyer':'Seller'} pipeline`,`${a.length} opportunities across ${stages.length} stages.`,`<button class="btn primary" data-add="opportunities" data-type="${type}">＋ Add opportunity</button>`)+`<div class="pipeline">${stages.map(stage=>`<section class="column"><div class="column-head"><span>${stage}</span>${badge(a.filter(x=>x.stage===stage).length,'gray')}</div>${a.filter(x=>x.stage===stage).map(x=>`<article class="opp clickable" data-contact="${x.contact_id}" title="Open ${esc(x.contact_name)}"><h3>${esc(x.contact_name)}</h3><p>${esc(x.title||`${type} opportunity`)}</p><label class="stage-control">Estimated value<input class="opp-value" data-opportunity="${x.id}" type="number" min="0" step="1000" value="${Number(x.value||0)}"></label><label class="stage-control">Stage<select class="opp-stage" data-opportunity="${x.id}">${stages.map(s=>`<option value="${s}" ${s===x.stage?'selected':''}>${s}</option>`).join('')}</select></label></article>`).join('')}</section>`).join('')}</div>`;bind();}
function taskRow(x){if(x._calendar)return `<div class="list-item"><button class="icon milestone-complete" data-transaction="${x.transaction_id}" data-milestone="${x.milestone_key}" title="${x.status==='completed'?'Completed':'Mark complete'}">${x.status==='completed'?'●':'○'}</button><div class="grow"><p>${esc(x.title)}</p><small>${esc(x.contact_name||'Transaction')} · ${fmtDateTime(x.due_at)}</small></div>${calendarAction(x.title,x.due_at,x.contact_name||'CRM transaction milestone','Add')}${badge(x.status==='completed'?'Completed':'Transaction',x.status==='completed'?'gray':'gold')}</div>`;return `<div class="list-item"><button class="icon task-complete" data-id="${x.id}" title="Complete">${x.status==='completed'?'●':'○'}</button><div class="grow"><p>${esc(x.title)}</p><small>${esc(x.contact_name||'General')} · ${fmtDateTime(x.due_at)} · ${esc(x.priority)}${x.status!=='completed'&&Number(x.reminder_minutes)>0?` · Reminder ${esc(reminderLabel(x.reminder_minutes))}`:''}</small></div>${calendarAction(x.title,x.due_at,[x.contact_name,x.notes].filter(Boolean).join(' — '),'Add')}<button class="btn task-edit" data-id="${x.id}">Edit</button>${badge(x.status==='completed'?'Completed':x.priority,x.priority==='High'?'red':'gray')}</div>`}
function eventRow(x){return `<div class="event"><h4>${esc(x.type)}${x.direction?` · ${esc(x.direction)}`:''}</h4><p>${esc(x.subject||x.body||'Activity logged')}</p><small>${esc(x.contact_name||'General')} · ${fmtDate(x.occurred_at)}</small></div>`}
function bindTaskActions(){$$('.task-complete').forEach(b=>b.onclick=async()=>{if(b.textContent==='●')return;await api('/tasks/'+b.dataset.id,{method:'PUT',body:JSON.stringify({status:'completed',completed_at:new Date().toISOString()})});toast('Task completed');go('tasks')});$$('.task-edit').forEach(b=>b.onclick=()=>{const task=state.data.tasks.find(x=>!x._calendar&&x.id===Number(b.dataset.id));if(task)openForm('tasks',task,task.id)});$$('.milestone-complete').forEach(b=>b.onclick=async()=>{if(b.textContent==='●')return;const tx=state.data.transactions.find(x=>x.id===Number(b.dataset.transaction)),completed=[...new Set([...(tx.completed_milestones||[]),b.dataset.milestone])];await api('/transactions/'+tx.id,{method:'PUT',body:JSON.stringify({completed_milestones:completed})});toast('Transaction milestone completed');go('tasks')})}
function bindContactRows(){$$('.contact-row').forEach(r=>r.onclick=e=>{if(e.target.closest('.contact-action,.contact-link'))return;showContact(Number(r.dataset.id))});$$('.contact-action,.contact-link').forEach(a=>a.onclick=e=>e.stopPropagation())}
function bind(){$$('[data-view]').forEach(x=>x.onclick=()=>go(x.dataset.view));$$('[data-add]').forEach(x=>x.onclick=()=>openForm(x.dataset.add,{type:x.dataset.type}));$$('.opp[data-contact]').forEach(x=>x.onclick=()=>showContact(Number(x.dataset.contact)));$$('.opp-stage').forEach(x=>{x.onclick=e=>e.stopPropagation();x.onchange=async e=>{e.stopPropagation();await api('/opportunities/'+x.dataset.opportunity,{method:'PUT',body:JSON.stringify({stage:x.value,status:['Closed','Nurture/Lost'].includes(x.value)?'closed':'active'})});toast('Pipeline stage updated');go(state.view);};});$$('.opp-value').forEach(x=>{x.onclick=e=>e.stopPropagation();x.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();x.blur();}};x.onchange=async e=>{e.stopPropagation();await api('/opportunities/'+x.dataset.opportunity,{method:'PUT',body:JSON.stringify({value:Number(x.value||0)})});toast('Opportunity value updated');};});bindContactRows();bindTaskActions();if(['listings','transactions'].includes(state.view)){$$('tbody tr').forEach((row,i)=>{const record=state.data[state.view]?.[i];if(!record)return;row.classList.add('clickable');row.title=`Open ${state.view==='listings'?'listing':'transaction'}`;row.onclick=()=>state.view==='transactions'?openTransaction(record):openForm('listings',record,record.id);});}if(state.contact&&$('#deleteContact')&&!$('#editContact')){const b=document.createElement('button');b.className='btn';b.id='editContact';b.textContent='Edit Contact';b.style.marginRight='8px';$('#deleteContact').before(b);b.onclick=()=>openForm('contacts',state.contact,state.contact.id);}}
async function showContact(id){await load('contacts','activities','tasks','opportunities');const c=state.data.contacts.find(x=>x.id===id);if(!c)return;state.contact=c;const acts=state.data.activities.filter(x=>x.contact_id===id),tasks=state.data.tasks.filter(x=>x.contact_id===id),opps=state.data.opportunities.filter(x=>x.contact_id===id);const phone=phoneHref(c.phone),email=String(c.email||'').trim();$('#app').innerHTML=header('CONTACT RECORD',`${esc(c.first_name)} ${esc(c.last_name)}`,'A complete view of this relationship.',`<button class="btn" data-view="contacts">← Contacts</button><button class="btn" id="applyPlan">Apply source plan</button><button class="btn" data-add="activities">Log activity</button>`)+`<div class="contact-layout"><section class="card profile"><div class="big-avatar">${initials(c)}</div><h2>${esc(c.first_name)} ${esc(c.last_name)}</h2><p>${(c.roles||[]).join(' · ')||'Contact'}</p>${contactActions(c)}<dl><dt>CELL</dt><dd>${phone?`<a class="contact-link" href="tel:${esc(phone)}">${esc(c.phone)}</a>`:'—'}</dd><dt>EMAIL</dt><dd>${email?`<a class="contact-link" href="mailto:${esc(email)}">${esc(c.email)}</a>`:'—'}</dd><dt>SPOUSE / PARTNER</dt><dd>${esc(c.partner||'—')}</dd><dt>PREFERRED CONTACT</dt><dd>${esc(c.preferred_contact)}</dd><dt>SOURCE</dt><dd>${esc(c.source)}</dd><dt>LAST CONTACT</dt><dd>${fmtDate(c.last_contact)}</dd><dt>NEXT FOLLOW-UP</dt><dd>${fmtDate(c.next_follow_up)}</dd><dt>TAGS</dt><dd>${(c.tags||[]).map(x=>badge(x,'gray')).join(' ')||'—'}</dd></dl><button class="btn danger" id="deleteContact">Delete contact</button></section><section class="card"><div class="tabs"><button class="tab active" data-contact-tab="timeline">Timeline</button><button class="tab" data-contact-tab="documents">Documents</button></div><div id="contactPanel"></div></section></div>`;const drawTimeline=()=>{$('#contactPanel').innerHTML=`<div class="timeline"><div class="event"><h4>Notes</h4><p>${esc(c.notes||'No notes yet.')}</p></div>${acts.map(eventRow).join('')}${opps.map(x=>`<div class="event"><h4>${esc(x.type)} opportunity · ${esc(x.stage)}</h4><p>${esc(x.title||'Pipeline opportunity')} · ${fmtMoney(x.value)}</p><small>${fmtDate(x.updated_at)}</small></div>`).join('')}${tasks.map(x=>`<div class="event"><h4>Task · ${esc(x.status)}</h4><p>${esc(x.title)}</p><small>Due ${fmtDateTime(x.due_at)}</small></div>`).join('')}</div>`};const drawDocuments=async()=>{const docs=await api(`/contacts/${id}/documents`);$('#contactPanel').innerHTML=`<div class="form-grid"><label class="field full"><span>Upload document</span><input type="file" id="contactFile"><small>PDF, image, Word, or other files up to 20 MB.</small></label><div class="form-actions"><button type="button" class="btn primary" id="uploadContactDocument">Upload</button></div><div class="field full"><span>Contact documents</span><div class="document-list">${docs.length?docs.map(d=>`<div class="list-item"><div class="grow"><p>${esc(d.filename)}</p><small>${(d.size_bytes/1024).toFixed(1)} KB · ${fmtDate(d.created_at)}</small></div><a class="btn" href="/api/contact-documents/${d.id}/download">Download</a><button type="button" class="btn danger delete-contact-document" data-id="${d.id}">Remove</button></div>`).join(''):empty('No documents uploaded','Upload identification, agreements, pre-approval letters, or other client files here.')}</div></div></div>`;$('#uploadContactDocument').onclick=async()=>{const file=$('#contactFile').files[0];if(!file)return toast('Choose a document first',true);if(file.size>20e6)return toast('Documents must be 20 MB or smaller',true);const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});await api(`/contacts/${id}/documents`,{method:'POST',body:JSON.stringify({filename:file.name,mime_type:file.type,data})});toast('Document uploaded');drawDocuments()};$$('.delete-contact-document').forEach(b=>b.onclick=async()=>{if(confirm('Remove this document from the contact?')){await api(`/contact-documents/${b.dataset.id}`,{method:'DELETE'});toast('Document removed');drawDocuments()}})};$$('[data-contact-tab]').forEach(tab=>tab.onclick=()=>{$$('[data-contact-tab]').forEach(x=>x.classList.toggle('active',x===tab));tab.dataset.contactTab==='documents'?drawDocuments():drawTimeline()});bind();drawTimeline();$('#applyPlan').onclick=async()=>{const r=await api(`/contacts/${id}/apply-plan`,{method:'POST'});toast(r.created?`${r.created} follow-up tasks created`:'No active plan for this source')};$('#deleteContact').onclick=async()=>{if(confirm('Delete this contact and related activities/opportunities?')){await api('/contacts/'+id,{method:'DELETE'});toast('Contact deleted');go('contacts')}};}
