async function openForm(table,defaults={},editId=null){await load('contacts');if(table==='transactions'||table==='listings')await load('listings');const names={contacts:'contact',opportunities:'opportunity',listings:'listing',transactions:'transaction',tasks:'task',activities:'activity'};$('#modalKicker').textContent=editId?'EDIT RECORD':'NEW RECORD';$('#modalTitle').textContent=`${editId?'Edit':'Add'} ${names[table]}`;const fs=fields[table].filter(f=>!(editId&&f[0]==='apply_plan'));$('#modalForm').innerHTML=`<div class="form-grid">${fs.map(f=>fieldHtml(f,defaults)).join('')}<div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">${editId?'Save changes':`Save ${names[table]}`}</button></div></div>`;$('#modal').classList.remove('hidden');$('#cancelModal').onclick=closeModal;const type=$('[name=type]');if(type)type.onchange=updateStage;updateStage();$('#modalForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),obj={};for(const [k,v]of fd)obj[k]=v;for(const f of fs){if(f[2]==='number')obj[f[0]]=Number(obj[f[0]]||0);if(f[0]==='roles')obj.roles=fd.getAll('roles');if(f[0]==='tags')obj.tags=String(obj.tags||'').split(',').map(x=>x.trim()).filter(Boolean);if(['open_houses','price_changes','documents','deadlines','feature_highlights','gallery_urls','public_documents'].includes(f[0]))obj[f[0]]=String(obj[f[0]]||'').split('\n').map(x=>x.trim()).filter(Boolean);if(f[2]==='checkbox')obj[f[0]]=fd.has(f[0]);if(['contact_id','seller_id','buyer_id','listing_id'].includes(f[0]))obj[f[0]]=obj[f[0]]?Number(obj[f[0]]):null;}try{const saved=await api('/'+table+(editId?'/'+editId:''),{method:editId?'PUT':'POST',body:JSON.stringify(obj)});closeModal();toast(editId?`${names[table][0].toUpperCase()+names[table].slice(1)} updated`:`${names[table][0].toUpperCase()+names[table].slice(1)} saved`);if(table==='listings'){await go('listings');const listing=(state.data.listings||[]).find(x=>x.id===saved.id)||saved;const count=matchingBuyers(listing).length;if(count)openListingMatches(listing)}else if(editId&&table==='contacts')showContact(editId);else if(state.contact&&table==='activities')showContact(state.contact.id);else go(state.view)}catch(err){toast(err.message,true)}};}
function fieldHtml([name,label,type,arg],defaults){const raw=defaults[name]??(name==='occurred_at'?new Date().toISOString().slice(0,10):name==='reminder_minutes'?60:''),value=type==='date'&&raw?String(raw).slice(0,10):type==='datetime-local'&&raw?String(raw).slice(0,16):Array.isArray(raw)?raw.join('\n'):raw;const full=['notes','body','marketing_notes','public_description','feature_highlights','gallery_urls','public_documents','open_houses','price_changes','documents','deadlines'].includes(name)?' full':'';let input='';if(type==='select'){const options=Array.isArray(arg?.[0])?arg:arg.map(x=>[x,x||'— Select —']);input=`<select name="${name}">${options.map(([option,text])=>`<option value="${esc(option)}" ${String(option)===String(value)?'selected':''}>${esc(text)}</option>`).join('')}</select>`}else if(type==='roles')input=`<div class="role-picks">${['Buyer','Seller','Agent','Past Client'].map(x=>`<label><input type="checkbox" name="roles" value="${x}" ${(Array.isArray(value)?value:[]).includes(x)?'checked':''}> ${x}</label>`).join('')}</div><small>Select Buyer or Seller to create its pipeline automatically.</small>`;else if(type==='textarea')input=`<textarea name="${name}">${esc(value)}</textarea>`;else if(type==='contact')input=`<select name="${name}"><option value="">— None —</option>${state.data.contacts.map(c=>`<option value="${c.id}" ${String(value||state.contact?.id||'')===String(c.id)?'selected':''}>${esc(c.first_name)} ${esc(c.last_name)}</option>`).join('')}</select>`;else if(type==='listing')input=`<select name="${name}"><option value="">— None —</option>${(state.data.listings||[]).map(x=>`<option value="${x.id}" ${String(value)===String(x.id)?'selected':''}>${esc(x.address)}</option>`).join('')}</select>`;else if(type==='stage')input=`<select name="${name}" id="stageSelect"></select>`;else if(type==='checkbox')return `<label class="field full"><span><input type="checkbox" name="${name}" checked> ${label}</span></label>`;else input=`<input name="${name}" type="${type}" value="${esc(value)}" ${arg===1?'required':''}>`;return `<label class="field${full}"><span>${label}</span>${input}</label>`}
function updateStage(){const s=$('#stageSelect');if(!s)return;const type=$('[name=type]')?.value||'buyer';s.innerHTML=(type==='seller'?sellerStages:buyerStages).map(x=>`<option>${x}</option>`).join('')}
